"""Local approximation of the lightlag server for offline testing."""
import math, random, copy

RULES = None


def default_rules():
    return {
        "delay_ticks": 3, "max_ticks": 50, "initial_battery": 100.0, "idle_cost": 0.5,
        "drive_cost": 1.0, "sample_cost": 3.0, "target_radius": 0.75, "base_radius": 0.75,
        "max_commands_per_uplink": 5, "max_metres_per_drive": 5.0,
        "slip_ranges": {"bedrock": [0.0, 0.05], "sand": [0.2, 0.45]},
        "slip_noise": [-0.02, 0.02],
        "terrain_drive_multipliers": {"bedrock": 1.0, "sand": 2.0},
        "sensing": {"position_noise_m": 0.6, "visual_odometry_noise": 0.1, "heading_bias_deg": 10.0,
                    "heading_bias_walk_deg": 1.0, "heading_noise_deg": 3.0},
        "sample_windows": {"late_fraction": 0.25},
    }


def in_rect(x, y, r):
    return r["x1"] <= x <= r["x2"] and r["y1"] <= y <= r["y2"]


def gen_map(rng):
    W = H = 40.0
    base = (20.0, 20.0)
    sand = []
    for _ in range(2):
        w, h = rng.uniform(6, 12), rng.uniform(6, 12)
        cx, cy = base[0] + rng.uniform(-12, 12), base[1] + rng.uniform(-12, 12)
        sand.append({"x1": cx - w / 2, "y1": cy - h / 2, "x2": cx + w / 2, "y2": cy + h / 2})
    hazards = []
    for sz in ([2, 4], [1, 2.5]):
        while True:
            w, h = rng.uniform(*sz), rng.uniform(*sz)
            d, a = rng.uniform(4, 10), rng.uniform(0, 2 * math.pi)
            cx, cy = base[0] + d * math.cos(a), base[1] + d * math.sin(a)
            r = {"x1": cx - w / 2, "y1": cy - h / 2, "x2": cx + w / 2, "y2": cy + h / 2}
            if not (r["x1"] - 1.5 < base[0] < r["x2"] + 1.5 and r["y1"] - 1.5 < base[1] < r["y2"] + 1.5):
                hazards.append(r)
                break

    def ok(x, y, pts):
        for hz in hazards:
            dx = max(hz["x1"] - x, 0, x - hz["x2"]); dy = max(hz["y1"] - y, 0, y - hz["y2"])
            if math.hypot(dx, dy) < 1.2:
                return False
        for p in pts + [base]:
            if math.hypot(p[0] - x, p[1] - y) < 3.0:
                return False
        return True

    targets = []
    pts = []
    i = 1
    while len(targets) < 5:
        d, a = rng.uniform(3, 9), rng.uniform(0, 2 * math.pi)
        x, y = base[0] + d * math.cos(a), base[1] + d * math.sin(a)
        if ok(x, y, pts):
            pts.append((x, y))
            v = rng.choice([1, 2])
            targets.append({"id": "t%d" % i, "x": x, "y": y, "value": v, "deadline_tick": rng.randint(10, 32),
                            "late_value": v * 0.25, "appear_tick": 0})
            i += 1
    nd = rng.randint(1, 2)
    while nd > 0:
        d, a = rng.uniform(3, 8), rng.uniform(0, 2 * math.pi)
        x, y = base[0] + d * math.cos(a), base[1] + d * math.sin(a)
        if ok(x, y, pts):
            pts.append((x, y))
            v = rng.choice([2, 3])
            ap = rng.randint(6, 24)
            targets.append({"id": "t%d" % i, "x": x, "y": y, "value": v, "deadline_tick": ap + rng.randint(6, 12),
                            "late_value": v * 0.25, "appear_tick": ap})
            i += 1
            nd -= 1
    return {"width": W, "height": H, "base": list(base), "sand": sand, "hazards": hazards, "targets": targets}


class Sim:
    def __init__(self, seed, missions=1):
        self.rng = random.Random(seed)
        self.missions = missions
        self.mission = 0
        self.scores = []
        self.campaign_complete = False
        self._new_mission()

    def _new_mission(self):
        self.mission += 1
        self.r = default_rules()
        self.r["campaign"] = {"missions": self.missions, "mission": self.mission}
        self.world = gen_map(self.rng)
        self.tick = 0
        self.pos = list(self.world["base"])
        self.bat = self.r["initial_battery"]
        s = self.r["sensing"]
        self.bias = math.radians(self.rng.uniform(-s["heading_bias_deg"], s["heading_bias_deg"]))
        self.coef = {k: self.rng.uniform(*v) for k, v in self.r["slip_ranges"].items()}
        self.queue = {}
        self.last_res = 0
        self.alive = True
        self.sampled = []
        self.sample_ticks = {}
        self.packets = [{"tick": 0, "received_tick": 0, "position": list(self.pos), "heading_deg": 0.0,
                         "battery": self.bat, "terrain": self.terrain(*self.pos), "wheel_odometry": 0,
                         "visual_odometry": 0, "sampled_targets": [], "alive": True, "events": []}]
        self.delivered = 1
        self.heading = 0.0

    def terrain(self, x, y):
        for s in self.world["sand"]:
            if in_rect(x, y, s):
                return "sand"
        return "bedrock"

    def rules(self):
        return copy.deepcopy(self.r)

    def map(self):
        w = copy.deepcopy(self.world)
        d = self.r["delay_ticks"]
        w["targets"] = [t for t in w["targets"] if t["appear_tick"] == 0 or t["appear_tick"] + d <= self.tick]
        return w

    def telemetry_log(self):
        d = self.r["delay_ticks"]
        out = []
        for p in self.packets:
            if p["tick"] + d <= self.tick or p["tick"] == 0:
                q = dict(p); q["received_tick"] = max(p["tick"] + d, 0) if p["tick"] else 0
                out.append(q)
        return out

    def uplink(self, cmds):
        d = self.r["delay_ticks"]
        first = max(self.tick + d + 1, self.last_res + 1)
        if first + len(cmds) - 1 > self.r["max_ticks"]:
            raise ValueError("too late")
        acks = []
        for i, c in enumerate(cmds):
            self.queue[first + i] = c
            acks.append({"execute_tick": first + i, "command": c})
        self.last_res = first + len(cmds) - 1
        return acks

    def _step(self):
        self.tick += 1
        t = self.tick
        s = self.r["sensing"]
        ev = []
        self.bat -= self.r["idle_cost"]
        wheel = 0.0; dist = 0.0
        c = self.queue.pop(t, None)
        if self.alive and c is not None and self.bat > 0:
            if c["action"] == "drive":
                self.heading = c["heading_deg"]
                self.bias += math.radians(self.rng.gauss(0, s["heading_bias_walk_deg"]))
                h = math.radians(c["heading_deg"]) + self.bias + math.radians(self.rng.gauss(0, s["heading_noise_deg"]))
                noise = self.rng.uniform(*self.r["slip_noise"])
                rem = c["metres"]
                while rem > 1e-9:
                    st = min(0.1, rem)
                    ter = self.terrain(*self.pos)
                    slip = min(max(self.coef[ter] + noise, 0), 0.9)
                    nx = self.pos[0] + st * (1 - slip) * math.cos(h)
                    ny = self.pos[1] + st * (1 - slip) * math.sin(h)
                    bad = not (0 <= nx <= self.world["width"] and 0 <= ny <= self.world["height"]) or any(
                        in_rect(nx, ny, hz) for hz in self.world["hazards"])
                    if bad:
                        ev.append({"type": "safety_stop"})
                        for k in list(self.queue):
                            if k > t:
                                del self.queue[k]
                        break
                    self.bat -= st * self.r["drive_cost"] * self.r["terrain_drive_multipliers"][ter]
                    dist += st * (1 - slip)
                    self.pos = [nx, ny]
                    wheel += st
                    rem -= st
            elif c["action"] == "sample":
                self.bat -= self.r["sample_cost"]
                best = None
                for tg in self.world["targets"]:
                    if tg["id"] in self.sampled or tg["appear_tick"] > t:
                        continue
                    dd = math.hypot(tg["x"] - self.pos[0], tg["y"] - self.pos[1])
                    if dd <= self.r["target_radius"] and (best is None or dd < best[0]):
                        best = (dd, tg)
                if best:
                    self.sampled.append(best[1]["id"]); self.sample_ticks[best[1]["id"]] = t
                    ev.append({"type": "sampled", "id": best[1]["id"]})
                else:
                    ev.append({"type": "sample_failed"})
        if self.bat <= 0:
            self.bat = 0; self.alive = False
        for tg in self.world["targets"]:
            if tg["appear_tick"] == t and t > 0:
                ev.append({"type": "target_discovered", "id": tg["id"]})
        pn = s["position_noise_m"]
        self.packets.append({"tick": t, "position": [self.pos[0] + self.rng.gauss(0, pn), self.pos[1] + self.rng.gauss(0, pn)],
                             "heading_deg": self.heading, "battery": self.bat, "terrain": self.terrain(*self.pos),
                             "wheel_odometry": wheel, "visual_odometry": dist * (1 + self.rng.gauss(0, s["visual_odometry_noise"])),
                             "sampled_targets": list(self.sampled), "alive": self.alive, "events": ev})

    def score(self):
        tot = sum(t["value"] for t in self.world["targets"])
        got = 0
        for tid in self.sampled:
            tg = [t for t in self.world["targets"] if t["id"] == tid][0]
            got += tg["value"] if self.sample_ticks[tid] <= tg["deadline_tick"] else tg["late_value"]
        b = self.world["base"]
        if not self.alive:
            m = 0
        elif math.hypot(self.pos[0] - b[0], self.pos[1] - b[1]) <= self.r["base_radius"]:
            m = 1
        else:
            m = 0.5
        return got * m / tot, got, tot, m

    def advance(self, n=1):
        d = self.r["delay_ticks"]
        if self.tick >= self.r["max_ticks"]:
            self.scores.append(self.score())
            if self.mission >= self.missions:
                self.campaign_complete = True
                return {"current_tick": self.tick, "episode_complete": True, "campaign_complete": True,
                        "mission": self.mission, "packets": []}
            self._new_mission()
            return {"current_tick": 0, "episode_complete": False, "campaign_complete": False,
                    "mission": self.mission, "packets": []}
        for _ in range(n):
            if self.tick >= self.r["max_ticks"]:
                break
            self._step()
        new = [p for p in self.telemetry_log() if p["tick"] >= self.delivered]
        self.delivered = max([p["tick"] for p in new] + [self.delivered - 1]) + 1
        done = self.tick >= self.r["max_ticks"]
        return {"current_tick": self.tick, "episode_complete": done, "campaign_complete": False,
                "mission": self.mission, "packets": new}

