new='''    def sand_len(self, p, q):
        ivs = []
        for s in self.sand:
            c = seg_rect_clip(p, q, s, 0.0)
            if c:
                ivs.append(c)
        if not ivs:
            return 0.0
        ivs.sort()
        tot = 0.0
        a, b = ivs[0]
        for c, d in ivs[1:]:
            if c > b:
                tot += b - a
                a, b = c, d
            else:
                b = max(b, d)
        tot += b - a
        return tot * math.hypot(q[0] - p[0], q[1] - p[1])

    def seg_clear(self, p, q, infl):
        for h in self.hazards:
            i = infl
            if in_rect(p[0], p[1], h, infl):
                i = 0.05
            if seg_rect_clip(p, q, h, i) is not None:
                return False
        if not (0.3 <= q[0] <= self.W - 0.3 and 0.3 <= q[1] <= self.H - 0.3):
            return False
        return True

    def build_corners(self):
        infl = CFG["inflate"]
        pts = []
        for h in self.hazards:
            e = infl + 0.1
            pts += [(h["x1"] - e, h["y1"] - e), (h["x2"] + e, h["y1"] - e), (h["x1"] - e, h["y2"] + e), (h["x2"] + e, h["y2"] + e)]
        for s in self.sand:
            e = 0.15
            pts += [(s["x1"] - e, s["y1"] - e), (s["x2"] + e, s["y1"] - e), (s["x1"] - e, s["y2"] + e), (s["x2"] + e, s["y2"] + e)]
        out = []
        for c in pts:
            if any(in_rect(c[0], c[1], hh, infl) for hh in self.hazards):
                continue
            if not (0.5 <= c[0] <= self.W - 0.5 and 0.5 <= c[1] <= self.H - 0.5):
                continue
            out.append(c)
        self.corners = out
        self.geo = {}

    def geom(self, p, q):
        key = (p, q)
        g = self.geo.get(key)
        if g is None:
            L = math.hypot(q[0] - p[0], q[1] - p[1])
            ok = self.seg_clear(p, q, CFG["inflate"] - 0.05)
            g = (L, self.sand_len(p, q), ok)
            if len(self.geo) < 200000:
                self.geo[key] = g
        return g

    def seg_cost(self, p, q, sb, ss):
        L, Ls, ok = self.geom(p, q)
        if not ok:
            return math.inf, 0, 0
        Lb = L - Ls
        wheel = Lb / (1 - sb) + Ls / (1 - ss)
        energy = self.dcost * (Lb / (1 - sb) * self.mult.get("bedrock", 1) + Ls / (1 - ss) * self.mult.get("sand", 2))
        ticks = math.ceil(wheel / self.maxm - 0.03) if wheel > 0.15 else 0
        return energy, ticks, wheel

    def dijkstra(self, src, dsts, sb, ss):
        """Energy-shortest paths from src to each dst. Returns list of (energy, ticks, pts)."""
        nodes = [src] + list(dsts) + self.corners
        nd = len(dsts)
        n = len(nodes)
        dist = [math.inf] * n
        tk = [0] * n
        prev = [-1] * n
        dist[0] = 0.0
        done = [False] * n
        remaining = nd
        while True:
            u = -1
            bu = math.inf
            for i in range(n):
                if not done[i] and dist[i] < bu:
                    u, bu = i, dist[i]
            if u < 0:
                break
            done[u] = True
            if 1 <= u <= nd:
                remaining -= 1
                if remaining == 0:
                    break
                continue  # do not route through targets
            for v in range(1, n):
                if done[v]:
                    continue
                e, t, _ = self.seg_cost(nodes[u], nodes[v], sb, ss)
                if dist[u] + e + 0.01 < dist[v]:
                    dist[v] = dist[u] + e + 0.01
                    tk[v] = tk[u] + t
                    prev[v] = u
        out = []
        for j in range(1, nd + 1):
            if dist[j] == math.inf:
                out.append((math.inf, 99, [nodes[j]]))
                continue
            pts = []
            v = j
            while v != 0:
                pts.append(nodes[v])
                v = prev[v]
            out.append((dist[j], tk[j], pts[::-1]))
        return out

    def path(self, p, q, sb=0.03, ss=0.33):
        r = self.dijkstra(p, [q], sb, ss)[0]
        return r[2]

'''
src=src[:start]+new+src[end:]
open('autopilot.py','w').write(src)
